let lang = $state(localStorage.getItem('lang') || 'id')
document.documentElement.lang = lang
export const i18n = {
  get lang() { return lang },
  toggle() { lang = lang === 'id' ? 'en' : 'id'; localStorage.setItem('lang', lang); document.documentElement.lang = lang },
  t: (k) => dict[lang][k] ?? dict.id[k] ?? k,
}

// Narration helper: pick the sentence in the current language at the moment it is spoken.
export const L = (id, en) => (lang === 'en' ? en : id)
